#!/usr/bin/env node
// Generates src/ui/primitives/Icon/material-filled/<name>.tsx (mobile 02 §5.3 rule 2):
// the FILLED Material Symbols (weight 400, outlined family) as react-native-svg components,
// for the registry concepts with `materialFill` — expo-symbols' font cannot draw the FILL
// axis on Android yet (expo#46850). Source: @material-symbols/svg-400/outlined/<name>-fill.svg.
//   node scripts/gen-material-filled.mjs           write
//   node scripts/gen-material-filled.mjs --check   fail when a generated file is stale
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const mobileDir = fileURLToPath(new URL('..', import.meta.url));
const require = createRequire(join(mobileDir, 'package.json'));
const svgDir = join(dirname(require.resolve('@material-symbols/svg-400/package.json')), 'outlined');
const outDir = join(mobileDir, 'src/ui/primitives/Icon/material-filled');
const registry = readFileSync(join(mobileDir, '../../packages/design-tokens/src/icons.ts'), 'utf8');

// Every `material: '<name>', materialFill: true` entry of the registry (ICON_CONCEPTS + MOBILE_ICON_CONCEPTS).
const names = [...new Set([...registry.matchAll(/material: '([a-z0-9_]+)', materialFill: true/g)].map((m) => m[1]))].sort();
const pascal = (s) => s.split('_').map((p) => p[0].toUpperCase() + p.slice(1)).join('');
const HEADER = '// GENERATED by scripts/gen-material-filled.mjs from @material-symbols/svg-400 — do not edit.\n';

function component(name) {
  const svg = readFileSync(join(svgDir, `${name}-fill.svg`), 'utf8');
  const viewBox = /viewBox="([^"]+)"/.exec(svg)?.[1];
  const paths = [...svg.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1]);
  if (!viewBox || paths.length === 0) throw new Error(`unexpected SVG for ${name}`);
  return `${HEADER}import React from 'react';
import Svg, { Path } from 'react-native-svg';
import type { FilledGlyphProps } from './types';

export default function ${pascal(name)}Fill({ size, color }: FilledGlyphProps): React.ReactElement {
  return (
    <Svg width={size} height={size} viewBox="${viewBox}">
${paths.map((d) => `      <Path d="${d}" fill={color} />`).join('\n')}
    </Svg>
  );
}
`;
}

const files = new Map(names.map((n) => [`${n}.tsx`, component(n)]));
files.set('types.ts', `${HEADER}export interface FilledGlyphProps {\n  size: number;\n  /** Literal tone colour (useThemeColors). */\n  color: string;\n}\n`);
files.set(
  'index.ts',
  `${HEADER}import type React from 'react';\nimport type { FilledGlyphProps } from './types';\n${names.map((n) => `import ${pascal(n)}Fill from './${n}';`).join('\n')}\n\n/** Material name → filled glyph. */\nexport const MATERIAL_FILLED: Record<string, (props: FilledGlyphProps) => React.ReactElement> = {\n${names.map((n) => `  ${n}: ${pascal(n)}Fill,`).join('\n')}\n};\n`,
);

if (process.argv.includes('--check')) {
  const stale = [...files].filter(([f, c]) => !existsSync(join(outDir, f)) || readFileSync(join(outDir, f), 'utf8').replace(/\r\n/g, '\n') !== c);
  const extra = existsSync(outDir) ? readdirSync(outDir).filter((f) => !files.has(f)) : [];
  if (stale.length || extra.length) {
    console.error(`material-filled is stale: ${[...stale.map(([f]) => f), ...extra].join(', ')} — run node scripts/gen-material-filled.mjs`);
    process.exit(1);
  }
} else {
  if (existsSync(outDir)) for (const f of readdirSync(outDir)) if (!files.has(f)) rmSync(join(outDir, f));
  mkdirSync(outDir, { recursive: true });
  for (const [f, c] of files) writeFileSync(join(outDir, f), c);
  console.log(`material-filled: ${names.join(', ')}`);
}
